pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // Get initial state: since C has no public state that changes via assertionDisputedCallback,
        // we check that the function does not emit events or change any observable state.
        // The only public getter is optimisticAsserter() and there's no state mutating function
        // accessible to us. We use a proxy: we call assertionDisputedCallback and verify it doesn't revert.
        // But the bug is that the require is removed, so it should still succeed.
        // To differentiate, we need to observe a state change. Let's assume C has a hidden state
        // that we can indirectly observe. Since we cannot, we must use a different approach.
        // We'll observe that after the call, the contract's behavior is unchanged by calling
        // another function that would revert if state were corrupted.
        // Actually, the only difference is that without the require, anyone can call the function.
        // So we test that assertionDisputedCallback can be called by any address without reverting.
        // But in the reference, it reverts when called by non-optimisticAsserter.
        // So the property is: calling assertionDisputedCallback by a random user reverts in reference.
        // But that's exactly the provided difference. Let's re-read: The test must PASS on reference and FAIL on mutant.
        // The mutant removes the require, so the function becomes callable by anyone without revert.
        // Thus the invariant is: when called by an address other than the optimistic asserter, the call reverts.
        // But the test says: "The assertionDisputedCallback function always succeeds (does not revert) for any bytes32 input" was tried and it passed on mutant.
        // That means the reference also succeeds? Wait: In reference, onlyOptimisticAsserter reverts because msg.sender is not the asserter.
        // But we are deploying with address(this) as the asserter, and in setUp we create C with address(this) as the asserter address.
        // Actually the constructor takes address _optimisticAsserter, and we pass address(this). So in tests, msg.sender is test contract = optimistic asserter.
        // So calling assertionDisputedCallback from the test contract will NOT revert in reference either!
        // That's why the previous test passed on both. We need to call from a different address.
        // So the rule: assertionDisputedCallback reverts when called by an address that is NOT the optimistic asserter.
        // We'll use vm.prank to impersonate a random user.
        // The mutant removes the require, so it won't revert.
        // Thus the test: assertTrue(call reverts for reference, call succeeds for mutant) but we need one assert.
        // We must make the test PASS on reference (revert) and FAIL on mutant (doesn't revert).
        // So we assert that the call reverts. That will pass on reference, fail on mutant.
        // But we need fuzz over assertionId. The assertionId is the parameter.
        // So we test: assertionDisputedCallback reverts for any bytes32 when called by a random address.
        // But we must also ensure the address is not the asserter. We'll use a random address from the fuzz parameter.
        // However we need to generate random addresses. We can use address(uint160(uint256(keccak256(abi.encode(assertionId))))).
        // But it's tricky. Simpler: use a fixed address that is not the test contract.
        // But the fuzz should drive the parameters. We can use vm.assume to ensure caller is not the asserter.
        // Actually the fuzz parameter is assertionId; we can convert it to an address.
        // Let's use address(0xdead) as caller. But that's not fuzzed.
        // We need the assertionId to be the fuzz param. The caller can be derived from it.
        // We'll do: address caller = address(uint160(uint256(assertionId) % (2**160)));
        // Then bound to avoid zero address? We'll assume it's not address(this) which is the asserter.
        // Then call assertionDisputedCallback from that caller.
        // Assert that it reverts.
        // That will pass on reference (revert) and fail on mutant (no revert).
        address caller = address(uint160(uint256(assertionId) % (2**160)));
        vm.assume(caller != address(this) && caller != address(0));
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.assertionDisputedCallback.selector, assertionId));
        assertTrue(!success);
    }
}

